#include <bits/stdc++.h>
using namespace std;

int main(){
    // int 型の変数(箱)を3つ作る
    int N, A, B;

    // cin で入力を順番に受け取ることができる。「>>」で区切ること（<<ではない）
    cin >> N >> A >> B;

    // 求める答えは N - A + B である。answer という変数(箱)を用意して、これに計算結果を入れる
    int answer = N - A + B;

    // cout を使うと答えを出力することが出来る。「<<」で区切ること（>>ではない）
    // endl で改行する。
    cout << answer << endl;
}

